import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.CR-yHhk1.js";const g=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"sepia","text":"Agent sessions, agnostically","tagline":"One canonical IR, store drivers, and an ACP client for every coding agent.","actions":[{"theme":"brand","text":"Get started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Reference","link":"/reference/protocol"}]},"features":[{"title":"Canonical session IR","details":"Every agent's session store maps onto one intermediate representation — one model for titles, history, tool calls, and restores."},{"title":"Store drivers","details":"Per-agent adapter binaries speak ndjson JSON-RPC over stdio. Add an agent without touching sepia's core."},{"title":"Local session management","details":"sepia-session owns the mechanism — attach, prompt, cancel, permissions, restore/rewind, liveness probing. Orchestration policy lives in peregrin."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),n={name:"index.md"};function s(i,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Sepia is the agent-session abstraction: one canonical session IR, per-agent store drivers speaking ndjson JSON-RPC, an ACP client for every coding agent, and <code>sepia serve</code> — the stdio service orchestrators embed.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Every coding agent keeps sessions its own way — SQLite, JSONL, directory layouts. Sepia maps them all onto one IR so listing, exporting, converting, and driving sessions is agent-agnostic, and keeps the mechanism stable enough that peregrin can build policy on top without linking internals.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> session mechanism — the IR, store drivers, attach, prompt, restore/rewind, agent configs, <code>sepia serve</code>.</li><li><strong>Doesn&#39;t own:</strong> orchestration policy (<a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a>), distribution (<a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a>), surfaces (<a href="https://9aia.com/pavo/" target="_blank" rel="noreferrer">pavo</a>).</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>List and prompt a real session</td><td><a href="/sepia/tutorials/getting-started.html">Tutorial</a></td></tr><tr><td>Do a task (convert sessions, write a driver, drive <code>sepia serve</code>)</td><td><a href="/sepia/how-to/">How-to</a></td></tr><tr><td>Understand the design (IR, drivers, mechanism vs policy)</td><td><a href="/sepia/explanation/">Explanation</a></td></tr><tr><td>Look up a verb, wire method, or env var</td><td><a href="/sepia/reference/">Reference</a></td></tr></tbody></table>',8)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
